from __future__ import annotations

"""Domain types for a small blob store with ETag optimistic concurrency.

A blob holds opaque ``content`` (bytes) and an ``etag`` that the store changes
on every successful write. Callers do read-modify-write cycles against JSON
documents kept in a blob: they read the current ``(content, etag)``, change the
decoded document, then write back. The write carries a precondition describing
which version the caller believed it was changing. If the blob moved on since
that read, the write must be rejected so the caller can re-read and merge.
"""

from dataclasses import dataclass


WILDCARD = "*"


class BlobNotFound(KeyError):
    """Raised when a read or write targets a blob that does not exist."""


class PreconditionFailed(Exception):
    """Raised when an If-Match precondition does not match the live etag.

    Mirrors a 412 Precondition Failed from the storage service: the blob was
    changed by someone else between the caller's read and its write.
    """

    def __init__(self, blob_name: str, expected: str | None, actual: str | None) -> None:
        self.blob_name = blob_name
        self.expected = expected
        self.actual = actual
        super().__init__(
            f"precondition failed for {blob_name!r}: "
            f"expected etag {expected!r}, live etag {actual!r}"
        )


@dataclass(frozen=True)
class ReadResult:
    """What a reader gets back: the content plus the version it belongs to."""

    blob_name: str
    content: bytes
    etag: str

    def text(self, encoding: str = "utf-8") -> str:
        return self.content.decode(encoding)


@dataclass(frozen=True)
class WriteResult:
    """The outcome of a successful conditional write."""

    blob_name: str
    etag: str
    created: bool

    def as_dict(self) -> dict[str, object]:
        return {
            "blob_name": self.blob_name,
            "etag": self.etag,
            "created": self.created,
        }


@dataclass(frozen=True)
class WriteCondition:
    """Precondition for a write.

    ``if_match`` of ``None`` means "create only if absent". ``if_match`` of the
    wildcard ``*`` means "match whatever is there" (overwrite-always). Any other
    value means "only write if the live etag equals this exact string".
    """

    if_match: str | None = None

    @classmethod
    def expecting(cls, etag: str) -> "WriteCondition":
        return cls(if_match=etag)

    @classmethod
    def overwrite_always(cls) -> "WriteCondition":
        return cls(if_match=WILDCARD)

    @classmethod
    def create_if_absent(cls) -> "WriteCondition":
        return cls(if_match=None)

    def is_wildcard(self) -> bool:
        return self.if_match == WILDCARD

    def is_create_only(self) -> bool:
        return self.if_match is None

    def describe(self) -> str:
        if self.if_match is None:
            return "if-none-match"
        if self.if_match == WILDCARD:
            return "if-match:*"
        return f"if-match:{self.if_match}"


def is_concrete_etag(value: str | None) -> bool:
    """Whether ``value`` names one specific version (not absent, not wildcard)."""

    return value is not None and value != WILDCARD


def short_etag(etag: str | None, width: int = 8) -> str:
    if etag is None:
        return "<none>"
    return etag[:width]

