from __future__ import annotations

"""In-memory blob store with ETag-based optimistic concurrency.

Every blob keeps its content plus a server-assigned etag. The store mints a
fresh etag on each successful write, so two writes never share one. A write
carries a :class:`WriteCondition`; the store decides whether that condition is
satisfied against the *live* etag and either commits (new etag) or rejects with
:class:`PreconditionFailed`. The store never trusts an etag the caller computed
on its own — only the value it last handed out can match.
"""

import itertools

from blob_models import (
    BlobNotFound,
    PreconditionFailed,
    ReadResult,
    WriteCondition,
    WriteResult,
)


class _Blob:
    __slots__ = ("content", "etag")

    def __init__(self, content: bytes, etag: str) -> None:
        self.content = content
        self.etag = etag


class InMemoryBlobStore:
    """A tiny stand-in for a blob container keyed by name."""

    def __init__(self, container: str = "documents") -> None:
        self.container = container
        self._blobs: dict[str, _Blob] = {}
        self._counter = itertools.count(1)
        # Server-side write counters, useful for asserting lost-update behavior.
        self._writes = 0
        self._rejections = 0

    def _mint_etag(self) -> str:
        n = next(self._counter)
        return f'"0x{self.container}-{n:08d}"'

    def exists(self, blob_name: str) -> bool:
        return blob_name in self._blobs

    def live_etag(self, blob_name: str) -> str | None:
        blob = self._blobs.get(blob_name)
        return blob.etag if blob else None

    def read(self, blob_name: str) -> ReadResult:
        """Return the current content and the etag it belongs to."""

        blob = self._blobs.get(blob_name)
        if blob is None:
            raise BlobNotFound(blob_name)
        return ReadResult(blob_name=blob_name, content=blob.content, etag=blob.etag)

    def try_read(self, blob_name: str) -> ReadResult | None:
        return self.read(blob_name) if self.exists(blob_name) else None

    def _precondition_met(self, blob: _Blob | None, condition: WriteCondition) -> bool:
        """Decide whether ``condition`` is allowed against the live blob."""

        if condition.is_wildcard():
            # If-Match:* requires the blob to already exist, but matches any etag.
            return blob is not None
        if condition.is_create_only():
            # If-None-Match: only when nothing is there yet.
            return blob is None
        # Concrete etag: must equal the live one exactly.
        return blob is not None and blob.etag == condition.if_match

    def write(
        self,
        blob_name: str,
        content: bytes,
        condition: WriteCondition,
    ) -> WriteResult:
        """Commit ``content`` if ``condition`` holds, else raise 412/not-found."""

        blob = self._blobs.get(blob_name)
        if not self._precondition_met(blob, condition):
            self._rejections += 1
            if condition.is_create_only() and blob is not None:
                raise PreconditionFailed(blob_name, None, blob.etag)
            if blob is None:
                raise BlobNotFound(blob_name)
            raise PreconditionFailed(blob_name, condition.if_match, blob.etag)

        created = blob is None
        new_etag = self._mint_etag()
        self._blobs[blob_name] = _Blob(content=content, etag=new_etag)
        self._writes += 1
        return WriteResult(blob_name=blob_name, etag=new_etag, created=created)

    def overwrite(self, blob_name: str, content: bytes) -> WriteResult:
        """Unconditional overwrite. Convenience for seeding test fixtures."""

        condition = (
            WriteCondition.overwrite_always()
            if self.exists(blob_name)
            else WriteCondition.create_if_absent()
        )
        return self.write(blob_name, content, condition)

    def delete(self, blob_name: str) -> None:
        self._blobs.pop(blob_name, None)

    def names(self) -> list[str]:
        return sorted(self._blobs)

    def write_count(self) -> int:
        return self._writes

    def rejection_count(self) -> int:
        return self._rejections

    def snapshot(self) -> dict[str, str]:
        return {name: blob.etag for name, blob in self._blobs.items()}

    def size(self) -> int:
        return len(self._blobs)

