from __future__ import annotations

"""Decide what to do when a conditional write loses a race.

A read-modify-write loop reads ``(content, etag)``, computes a new document,
then writes with an If-Match precondition. If another writer committed first,
the store rejects the write. This module decides whether that rejection is
retryable, how many attempts are allowed, and packages the bookkeeping the
workflow reports back to billing/ops dashboards.
"""

from dataclasses import dataclass

from blob_models import BlobNotFound, PreconditionFailed


class RetryExhausted(Exception):
    """Raised when conditional writes kept losing the race past the budget."""

    def __init__(self, blob_name: str, attempts: int) -> None:
        self.blob_name = blob_name
        self.attempts = attempts
        super().__init__(
            f"gave up updating {blob_name!r} after {attempts} attempt(s)"
        )


@dataclass(frozen=True)
class RetryPolicy:
    """How many times to re-read and retry a conflicted write."""

    max_attempts: int = 5

    def __post_init__(self) -> None:
        if self.max_attempts < 1:
            raise ValueError("max_attempts must be >= 1")

    def attempts_remaining(self, used: int) -> int:
        return max(0, self.max_attempts - used)

    def has_budget(self, used: int) -> bool:
        return used < self.max_attempts


def is_concurrency_conflict(error: Exception) -> bool:
    """Whether ``error`` means 'someone else wrote first' (a 412)."""

    return isinstance(error, PreconditionFailed)


def is_missing_blob(error: Exception) -> bool:
    return isinstance(error, BlobNotFound)


def should_retry(error: Exception, attempts_used: int, policy: RetryPolicy) -> bool:
    """Whether a failed write should trigger a re-read and another attempt.

    A precondition failure is the one error we recover from: re-read the latest
    document, merge our change onto it, and try again while budget remains.
    A missing blob or any other error is not a race and must not be retried.
    """

    if not is_concurrency_conflict(error):
        return False
    return policy.has_budget(attempts_used)


@dataclass
class AttemptLog:
    """Per-update record of how the read-modify-write loop played out."""

    blob_name: str
    attempts: int = 0
    conflicts: int = 0
    committed_etag: str | None = None

    def record_attempt(self) -> None:
        self.attempts += 1

    def record_conflict(self) -> None:
        self.conflicts += 1

    def record_commit(self, etag: str) -> None:
        self.committed_etag = etag

    def succeeded(self) -> bool:
        return self.committed_etag is not None

    def as_dict(self) -> dict[str, object]:
        return {
            "blob_name": self.blob_name,
            "attempts": self.attempts,
            "conflicts": self.conflicts,
            "committed_etag": self.committed_etag,
            "succeeded": self.succeeded(),
        }


def summarize_logs(logs: list[AttemptLog]) -> dict[str, object]:
    return {
        "update_count": len(logs),
        "total_attempts": sum(log.attempts for log in logs),
        "total_conflicts": sum(log.conflicts for log in logs),
        "all_succeeded": all(log.succeeded() for log in logs) if logs else True,
    }


def classify_error(error: Exception) -> str:
    if is_concurrency_conflict(error):
        return "precondition_failed"
    if is_missing_blob(error):
        return "not_found"
    return "other"

