from __future__ import annotations

"""Read-modify-write workflow for a JSON metadata document in a blob.

Callers ask to set a single metadata field. The updater reads the current blob,
decodes the document, applies the change, then writes the new bytes back under a
precondition so two writers racing on the same blob cannot silently clobber each
other. When the store reports the blob moved on, the conflict policy decides
whether to re-read and try again.
"""

from blob_models import PreconditionFailed, WriteCondition
from blob_store import InMemoryBlobStore
from conflict_policy import (
    AttemptLog,
    RetryExhausted,
    RetryPolicy,
    should_retry,
    summarize_logs,
)
from metadata_codec import (
    apply_change,
    decode_document,
    empty_document,
    encode_document,
    revision_of,
)


class DocumentUpdater:
    """Owns the read-modify-write loop for one blob container."""

    def __init__(
        self,
        store: InMemoryBlobStore,
        policy: RetryPolicy | None = None,
    ) -> None:
        self._store = store
        self._policy = policy if policy is not None else RetryPolicy()
        self._logs: list[AttemptLog] = []

    @property
    def store(self) -> InMemoryBlobStore:
        return self._store

    def _load(self, blob_name: str) -> tuple[dict[str, object], str | None]:
        """Read and decode the current document; (empty, None) if absent."""

        existing = self._store.try_read(blob_name)
        if existing is None:
            return empty_document(), None
        return decode_document(existing.content), existing.etag

    def update_field(self, blob_name: str, field: str, value: object) -> dict[str, object]:
        """Set ``field`` to ``value`` on the document, retrying on conflict."""

        log = AttemptLog(blob_name=blob_name)
        self._logs.append(log)
        attempts_used = 0

        while True:
            document, etag = self._load(blob_name)
            updated = apply_change(document, field, value)
            payload = encode_document(updated)
            condition = self._condition_for(etag)

            log.record_attempt()
            attempts_used += 1
            try:
                result = self._store.write(blob_name, payload, condition)
            except PreconditionFailed as conflict:
                log.record_conflict()
                if should_retry(conflict, attempts_used, self._policy):
                    continue
                raise RetryExhausted(blob_name, attempts_used) from conflict

            log.record_commit(result.etag)
            return {
                "blob_name": blob_name,
                "etag": result.etag,
                "revision": revision_of(updated),
                "field": field,
                "value": value,
                "attempts": log.attempts,
                "created": result.created,
            }

    def _condition_for(self, etag: str | None) -> WriteCondition:
        """Build the precondition for a write given the read's etag."""

        if etag is None:
            return WriteCondition.create_if_absent()
        return WriteCondition.overwrite_always()

    def read_document(self, blob_name: str) -> dict[str, object]:
        document, _ = self._load(blob_name)
        return document

    def field_value(self, blob_name: str, field: str, default: object = None) -> object:
        return self.read_document(blob_name).get(field, default)

    def current_revision(self, blob_name: str) -> int:
        return revision_of(self.read_document(blob_name))

    def logs(self) -> list[AttemptLog]:
        return list(self._logs)

    def summary(self) -> dict[str, object]:
        return summarize_logs(self._logs)


def apply_updates(
    store: InMemoryBlobStore,
    blob_name: str,
    changes: list[tuple[str, object]],
    policy: RetryPolicy | None = None,
) -> dict[str, object]:
    """Apply a sequence of field changes to one blob through one updater."""

    updater = DocumentUpdater(store, policy)
    last: dict[str, object] = {}
    for field, value in changes:
        last = updater.update_field(blob_name, field, value)
    return {"last": last, "summary": updater.summary()}

