from __future__ import annotations

"""Encode and decode the JSON document stored inside a blob.

The document is a flat mapping of metadata keys to JSON-serializable values
plus a ``revision`` integer the application bumps on every applied change. The
codec is deliberately strict about shape so a corrupt blob surfaces early rather
than silently producing an empty document.
"""

import json


REVISION_KEY = "revision"


class MetadataDecodeError(ValueError):
    """Raised when stored bytes are not a valid metadata document."""


def encode_document(document: dict[str, object]) -> bytes:
    """Serialize a metadata document to canonical, sorted JSON bytes."""

    if not isinstance(document, dict):
        raise TypeError("document must be a dict")
    payload = dict(document)
    payload.setdefault(REVISION_KEY, 0)
    if not isinstance(payload[REVISION_KEY], int):
        raise TypeError("revision must be an int")
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def decode_document(content: bytes) -> dict[str, object]:
    """Parse stored bytes back into a metadata document."""

    if content == b"":
        raise MetadataDecodeError("empty blob content")
    try:
        parsed = json.loads(content.decode("utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise MetadataDecodeError(str(exc)) from exc
    if not isinstance(parsed, dict):
        raise MetadataDecodeError("document root must be an object")
    parsed.setdefault(REVISION_KEY, 0)
    return parsed


def revision_of(document: dict[str, object]) -> int:
    value = document.get(REVISION_KEY, 0)
    if not isinstance(value, int):
        raise MetadataDecodeError("revision must be an int")
    return value


def apply_change(
    document: dict[str, object],
    field: str,
    value: object,
) -> dict[str, object]:
    """Return a new document with ``field`` set and the revision advanced."""

    if not field or field == REVISION_KEY:
        raise ValueError("invalid metadata field")
    updated = dict(document)
    updated[field] = value
    updated[REVISION_KEY] = revision_of(document) + 1
    return updated


def merge_change(
    latest: dict[str, object],
    field: str,
    value: object,
) -> dict[str, object]:
    """Re-apply a single field change on top of the latest document.

    This is what a retry should call after re-reading: it keeps every field
    another writer added and only layers this writer's own field on top.
    """

    return apply_change(latest, field, value)


def fields_of(document: dict[str, object]) -> list[str]:
    return sorted(key for key in document if key != REVISION_KEY)


def get_field(document: dict[str, object], field: str, default: object = None) -> object:
    return document.get(field, default)


def documents_equal(left: dict[str, object], right: dict[str, object]) -> bool:
    return encode_document(left) == encode_document(right)


def empty_document() -> dict[str, object]:
    return {REVISION_KEY: 0}


def describe_document(document: dict[str, object]) -> str:
    fields = ",".join(fields_of(document))
    return f"rev={revision_of(document)} fields=[{fields}]"

